"""Reproduce teaching SVGs and a source Figure 4 crop. Requires Poppler for crop."""
from pathlib import Path
from html import escape
import subprocess
out=Path(__file__).resolve().parents[1]/'public/figures/grokking'
out.mkdir(parents=True,exist_ok=True)
def text(x,y,s,size=19): return f'<text x="{x}" y="{y}" font-size="{size}">{escape(s)}</text>'
def box(x,y,a,b,c='#ddd9fa',w=270):
 return f'<rect x="{x}" y="{y}" width="{w}" height="90" rx="12" fill="{c}" stroke="#71849a"/>'+text(x+12,y+32,a)+text(x+12,y+65,b,16)
def arrow(x,y,a,b): return f'<path d="M{x} {y} L{a} {b}" stroke="#53677d" stroke-width="3" fill="none" marker-end="url(#a)"/>'
def svg(name,title,desc,body,h=440):
 (out/f'{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 940 {h}" role="img" aria-labelledby="t d"><title id="t">{escape(title)}</title><desc id="d">{escape(desc)}</desc><defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#53677d"/></marker></defs><rect width="940" height="{h}" rx="18" fill="#f3f6fb"/><g font-family="Arial,sans-serif" fill="#17304b">'+text(28,43,title,25)+body+'</g></svg>')
svg('problem','01 / The answer table is fitted before the rule is reusable','Conceptual checkpoints, not measured times.',box(30,100,'Initialization','Random symbol embeddings','#d4eee7')+arrow(310,145,345,145)+box(350,100,'Memorization','Training answers correct')+arrow(630,145,665,145)+box(670,100,'Generalization','Held-out answers improve',w=240)+box(30,270,'Training accuracy low','No useful decoder yet','#d4eee7')+box(350,270,'Validation accuracy low','Decoder fits arbitrary sums')+box(670,270,'Structure emerges','Pairs share decoder inputs','#ffe6cb',240)+text(30,415,'Same examples throughout; embeddings and decoder keep evolving.',18))
svg('architecture','02 / Ordinary addition: a trainable table and an MLP','Functional architecture from Section 2; unspecified decoder internals are not invented.',box(30,100,'A · Lookup symbols i, j','E: p × d-in; select two rows','#d4eee7')+arrow(310,145,345,145)+box(350,100,'B · Add embeddings','z = Eᵢ + Eⱼ; shape d-in')+arrow(630,145,665,145)+box(670,100,'C · MLP decoder θ','Output shape d-out',w=240)+box(30,270,'E · Update E and θ','Carry optimizer states')+arrow(340,315,310,315)+box(350,270,'Backpropagate','Gradients through C, B and A')+arrow(660,315,630,315)+box(670,270,'D · Task loss','Compare to fixed target Yᵢ₊ⱼ','#ffe6cb',240)+arrow(790,200,790,260)+text(30,414,'Regression: fixed random target vectors. Classification: one-hot targets and cross-entropy.',18))
svg('training','03 / Two optimizers, one prediction path','Train both modules; freeze both for held-out inference.',box(30,100,'Train pair + target','Fixed split and target vectors','#d4eee7')+arrow(310,145,345,145)+box(350,100,'A → B → C → D','Forward pass and task loss')+arrow(630,145,665,145)+box(670,100,'E · Adam / AdamW','Update table / decoder',w=240)+box(30,270,'Held-out pair only','Freeze E and θ','#d4eee7')+arrow(310,315,345,315)+box(350,270,'A → B → C','No loss or parameter update')+arrow(630,315,665,315)+box(670,270,'Prediction','Score with label afterwards','#ffe6cb',240)+text(30,415,'Optimizer moments and weights carry between training steps; inference receives no target.',18))
svg('representation','04 / Coincident midpoints mean identical sums','Affine embedding example E_k = (k,1); schematic positions.',arrow(60,190,880,190)+''.join(f'<circle cx="{x}" cy="190" r="9" fill="#218c77"/>'+text(x-18,232,f'E{k}',20) for x,k in [(170,5),(320,6),(620,8),(770,9)])+'<circle cx="470" cy="190" r="8" fill="#bc6d28"/><path d="M170 170 Q470 45 770 170 M320 175 Q470 100 620 175" fill="none" stroke="#8264b0" stroke-width="3"/>'+text(380,265,'Shared midpoint E7',18)+box(30,310,'Train: (6,8)','E6 + E8 = 2E7 = (14,2)','#d4eee7',420)+box(490,310,'Held out: (5,9)','E5 + E9 = 2E7 = (14,2)',w=420),440)
svg('numbers','05 / Reuse exactly the same decoder input','Computed teaching values, not trained parameters.',box(30,100,'A · Select E6 and E8','(6,1) and (8,1)','#d4eee7')+arrow(310,145,345,145)+box(350,100,'B · Sum = (14,2)','Identical input to C')+arrow(630,145,665,145)+box(670,100,'C · Learned mapping','Y14 = (0.2, −0.4)',w=240)+box(30,270,'A · Select E5 and E9','(5,1) and (9,1)','#d4eee7')+arrow(310,315,345,315)+box(350,270,'B · Sum = (14,2)','No new decoder rule needed')+arrow(630,315,665,315)+box(670,270,'Same output Y14','D · Training error was zero','#ffe6cb',240)+text(30,415,'Perturb E9 by (0.2,0): residual norm 0.2; squared mismatch 0.04.',18))
svg('dynamics','06 / Constraints select structure; slow modes set a timescale','Analytical path, not the training algorithm. Numerical values are illustrative.',box(30,100,'Training equal-sum pairs','Build A from +1,+1,−1,−1','#d4eee7')+arrow(310,145,345,145)+box(350,100,'Solve A R = 0','Nullity 2 → affine embeddings')+arrow(630,145,665,145)+box(670,100,'Linear relaxation','Mode ∝ exp(−λt)',w=240)+box(30,270,'η = 0.001; λ3 = 0.2','One e-fold: 5,000 steps','#d4eee7')+arrow(310,315,345,315)+box(350,270,'After 10,000 steps','Mode amplitude ≈ 0.135')+arrow(630,315,665,315)+box(670,270,'After 15,000 steps','Mode amplitude ≈ 0.050','#ffe6cb',240)+text(30,415,'The normalized quotient flow has an additional radial term; see the derivation in the guide.',17))
svg('phases','07 / Four outcomes within an observation window','Conceptual phase labels; these boxes are not measured phase boundaries.',box(30,100,'Comprehension','Train succeeds; validation soon','#d4eee7',420)+box(490,100,'Grokking','Train succeeds; validation much later',w=420)+box(30,270,'Memorization','Train succeeds; validation not reached','#ffe6cb',420)+box(490,270,'Confusion','Training criterion not reached','#e4e9ef',420)+text(30,415,'Rate and decay change the balance. Strong restriction can also prevent fitting.',18))
subprocess.run(['pdftoppm','-f','5','-singlefile','-scale-to','2000','-x','260','-y','175','-W','1030','-H','455','-png',str(out.parents[1]/'materials/da97193c2ba796d0.pdf'),str(out/'source-figure-4')],check=True)
assert abs((.2*(1-8*.1))**2-.0016)<1e-12
print('Generated seven teaching SVGs and source Figure 4; toy gradient arithmetic checked.')
